            globalThis.localStorage.setItem(config.STORAGE_KEY, 'true');
            Modal.close()
        };

        const handleClicks = (event) => {
            const isClose = event.target.closest(config.SELECTORS.CLOSE);
            const isAction = event.target.closest(config.SELECTORS.ANCHOR);

            if (isClose) {
                pushAnalytics('click:fechar');
                removeModal();
            } else if (isAction) {
                pushAnalytics('click:conhecer');
                removeModal();
            }
