            if (!hasGenericModal) return

            const imgClass = config.CONTENT.IMG_EXTRA_CLASS
                ? `awareness-modal-img ${config.CONTENT.IMG_EXTRA_CLASS}`
                : 'awareness-modal-img';
            const btnStyle = config.CONTENT.BTN_STYLE
                ? ` style="${config.CONTENT.BTN_STYLE}"`
                : '';

            const body = `
                <div class="modal-feedback">
                    <div class="modal-feedback-content">
                        <div class="modal-feedback-header">
                            <button class="flex fidelity-awareness-modal-icon-close" type="button" aria-label="Fechar">
<svg class="facelift-svg" width="10" height="10" viewBox="0 0 10 10" fill="none" xmlns="http://www.w3.org/2000/svg">
<path class="facelift-svg-path" d="M9.66671 1.27325L8.72671 0.333252L5.00004 4.05992L1.27337 0.333252L0.333374 1.27325L4.06004 4.99992L0.333374 8.72659L1.27337 9.66659L5.00004 5.93992L8.72671 9.66659L9.66671 8.72659L5.94004 4.99992L9.66671 1.27325Z" fill="#000000"/>
</svg>
                            </button>
                        </div>
                        <div class="awareness-modal-content-inner">
                            <div class="awareness-modal-img-wrapper">
                                <img class="${imgClass}"
                                    src="${config.CONTENT.IMG_SRC}" alt="${config.CONTENT.IMG_ALT}" />
                            </div>
                            <h1 class="awareness-modal-title-main">
                                ${config.CONTENT.TITLE}
                            </h1>
                            <p class="awareness-modal-subtitle">
                                ${config.CONTENT.DESCRIPTION}
                            </p>
                            <a href="${link}"${btnStyle} class="btn btn-lg btn-primary btn-block btn-gap btn-bold awareness-modal-anchor">
                                Conhecer
                            </a>
                        </div>
                    </div>
                </div>
                <div id="pace" class="feedback-blind modal-feedback-loading is-hidden">
                    <span class="pace-activity pace-feedback"></span>
                </div>
            `;

            let modalContainer;
            const shouldUseBottomSheet = isMobileViewport();
            Modal.open({
                title: '',
                body,
                hasCustomDismiss: true,
                hasCustomHeader: true,
