            ensureAuthenticatedToShow,
            ensureMemberToShow,
            hasLightbox,
            shouldSkipPath: (pathname) => presentationModalConfig.skipPaths?.some((path) => pathname?.startsWith(path))
        };
    };

    const resolveContent = (presentationModalConfig, fidelityConfig) => ({
